insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('de-donde-vienen-los-alimentos-que-comes-cada-dia','agricultura',array['ambiente']::text[],'¿De dónde vienen los alimentos que comes cada día?','Registra el origen de lo que comes durante unos días, usando etiquetas y preguntas en el mercado, y descubre cuántos de tus alimentos son locales, nacionales o importados.','Investigación','2 semanas',16,array['Origen de alimentos','Consumo']::text[],array['investigar']::text[],'propios',NULL,'ingenieria agroindustrial economia administracion logistica estadistica sociologia marketing ingenieria industrial registro. investigacion de campo. calculo de porcentajes. visualizacion. cuaderno de registro. hoja de calculo. un mapa sencillo.',$a34agr${"id": "de-donde-vienen-los-alimentos-que-comes-cada-dia", "area": "agricultura", "areas2": ["ambiente"], "titulo": "¿De dónde vienen los alimentos que comes cada día?", "resumen": "Registra el origen de lo que comes durante unos días, usando etiquetas y preguntas en el mercado, y descubre cuántos de tus alimentos son locales, nacionales o importados.", "tipo": "Investigación", "tiempo": "2 semanas", "horas": 16, "etiquetas": ["Origen de alimentos", "Consumo"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Agroindustrial", "Economía", "Administración", "Logística", "Estadística", "Sociología", "Marketing", "Ingeniería Industrial"], "problema": ["Casi nunca nos preguntamos de dónde vienen los alimentos que comemos. Algunos recorren cientos de kilómetros y otros salen de la chacra de al lado, pero eso solo se sabe si se averigua.", "Conocer el origen ayuda a entender la distancia, las estaciones y las decisiones de compra."], "desarrollar": ["Durante tres a cinco días anota todo lo que comes en una lista. Para cada alimento, averigua el origen leyendo etiquetas o preguntando en el mercado, y anota si es local, de otra región del país o importado.", "Calcula qué porcentaje de tus alimentos proviene de cada origen y presenta un mapa simple o un gráfico. Escribe qué te sorprendió y qué cambiarías si quisieras comer más producto local."], "ampliaciones": [{"titulo": "Distancia", "aporta": "estima los kilómetros que recorrió cada alimento."}, {"titulo": "Comparar hogares", "aporta": "compara tu registro con el de otro hogar, de forma anónima."}, {"titulo": "Propuesta", "aporta": "plantea cómo reemplazar tres alimentos por opciones más locales."}], "objetivos": ["Registrar lo que comes.", "Averiguar el origen.", "Calcular porcentajes.", "Reflexionar sobre alternativas."], "habilidades": ["Registro.", "Investigación de campo.", "Cálculo de porcentajes.", "Visualización."], "herramientas": ["Cuaderno de registro.", "Hoja de cálculo.", "Un mapa sencillo."], "lineamientos": ["Es un experimento pequeño y personal: pocas plantas o pocas muestras durante pocas semanas. No pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir en tu caso.", "No publiques lo que come tu familia con detalles personales; usa porcentajes y ejemplos generales.", "Pregunta con respeto en el mercado y acepta que no siempre habrá respuestas."], "otroSector": "El mismo ejercicio de rastrear el origen sirve para conocer de dónde vienen los materiales de cualquier producto o servicio."}$a34agr$::jsonb,41),
('el-viaje-de-un-alimento-del-campo-a-tu-mesa','agricultura',array['negocios']::text[],'El viaje de un alimento: del campo a tu mesa','Elige un alimento común y reconstruye su recorrido desde el campo hasta tu mesa, identificando quiénes participan, cuánto tarda y dónde cambia de precio.','Análisis','4 semanas',24,array['Cadena alimentaria','Ruta de abastecimiento']::text[],array['investigar']::text[],'publicos',NULL,'ingenieria agroindustrial economia administracion logistica estadistica sociologia marketing ingenieria industrial investigacion documental. diagramacion. analisis de procesos. comunicacion visual. informes publicos. una herramienta de diagramas. hoja de calculo.',$a35agr${"id": "el-viaje-de-un-alimento-del-campo-a-tu-mesa", "area": "agricultura", "areas2": ["negocios"], "titulo": "El viaje de un alimento: del campo a tu mesa", "resumen": "Elige un alimento común y reconstruye su recorrido desde el campo hasta tu mesa, identificando quiénes participan, cuánto tarda y dónde cambia de precio.", "tipo": "Análisis", "tiempo": "4 semanas", "horas": 24, "etiquetas": ["Cadena alimentaria", "Ruta de abastecimiento"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ingeniería Agroindustrial", "Economía", "Administración", "Logística", "Estadística", "Sociología", "Marketing", "Ingeniería Industrial"], "problema": ["Un alimento pasa por varias manos antes de llegar al plato: productor, acopiador, transportista, mercado y comerciante. Cada etapa añade tiempo, costos y posibles pérdidas, pero casi nunca se ve el recorrido completo.", "Mapearlo ayuda a entender de dónde viene el precio y dónde hay oportunidades de mejora."], "desarrollar": ["Elige un alimento, por ejemplo la papa o el plátano, y busca información pública sobre cómo se produce y distribuye. Identifica las etapas del recorrido, quiénes participan y cuánto tiempo y distancia hay entre cada una.", "Dibuja el recorrido en un diagrama con las etapas, los actores y, si hay datos, el precio en cada punto. Escribe un breve análisis de dónde ocurre más pérdida o encarecimiento y por qué."], "ampliaciones": [{"titulo": "Dos alimentos", "aporta": "compara el recorrido de un producto fresco y uno procesado."}, {"titulo": "Versión corta", "aporta": "diseña una cadena más corta con menos intermediarios."}, {"titulo": "Infografía", "aporta": "crea una infografía simple que cualquiera pueda entender."}], "objetivos": ["Elegir un alimento.", "Reconstruir sus etapas.", "Diagramar el recorrido.", "Analizar pérdidas y precios."], "habilidades": ["Investigación documental.", "Diagramación.", "Análisis de procesos.", "Comunicación visual."], "herramientas": ["Informes públicos.", "Una herramienta de diagramas.", "Hoja de cálculo."], "lineamientos": ["Indica de dónde salen los datos, con la fecha de consulta, y aclara que son referenciales y no sirven para decidir por tu cuenta qué sembrar o cuánto invertir.", "No acuses a ninguna persona o empresa: describe etapas y factores, no culpables.", "Si conversas con productores o vendedores, hazlo con su permiso, sin publicar nombres ni datos de contacto; si prefieren no participar, usa casos inventados."], "otroSector": "El mismo mapeo de etapas sirve para entender el recorrido de cualquier producto o servicio hasta su cliente."}$a35agr$::jsonb,42),
('estacionalidad-de-frutas-y-verduras-que-hay-en-cada-mes','agricultura',array['negocios']::text[],'Estacionalidad de frutas y verduras: qué hay en cada mes','Analiza en qué meses abundan o escasean las frutas y verduras de tu zona, y cómo cambia su disponibilidad y su precio a lo largo del año, con datos públicos de mercados.','Análisis','3 semanas',18,array['Estacionalidad','Frutas y verduras']::text[],array['investigar','crear']::text[],'publicos',NULL,'ingenieria agroindustrial economia administracion logistica estadistica sociologia marketing ingenieria industrial analisis de series. visualizacion. lectura de datos publicos. comunicacion. datos publicos de mercados. hoja de calculo. graficos.',$a36agr${"id": "estacionalidad-de-frutas-y-verduras-que-hay-en-cada-mes", "area": "agricultura", "areas2": ["negocios"], "titulo": "Estacionalidad de frutas y verduras: qué hay en cada mes", "resumen": "Analiza en qué meses abundan o escasean las frutas y verduras de tu zona, y cómo cambia su disponibilidad y su precio a lo largo del año, con datos públicos de mercados.", "tipo": "Análisis", "tiempo": "3 semanas", "horas": 18, "etiquetas": ["Estacionalidad", "Frutas y verduras"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ingeniería Agroindustrial", "Economía", "Administración", "Logística", "Estadística", "Sociología", "Marketing", "Ingeniería Industrial"], "problema": ["Los alimentos tienen temporada: cuando abundan son más baratos y frescos, y cuando escasean se encarecen. Mucha gente compra sin saberlo y paga más de lo necesario.", "Conocer la estacionalidad permite planificar compras y comidas, y entender mejor la agricultura de la zona."], "desarrollar": ["Reúne datos públicos de precios y de ingresos de productos a mercados mayoristas durante un año. Elige cinco o seis alimentos y marca en qué meses hay más oferta y precios más bajos, y en cuáles hay menos.", "Construye una gráfica de calor o una tabla por mes y producto, y escribe una guía de compras por temporada. Explica qué cambios dependen del clima y cuáles de otros factores."], "ampliaciones": [{"titulo": "Calendario de compras", "aporta": "diseña un calendario para planificar las comidas del mes."}, {"titulo": "Comparar zonas", "aporta": "repite el análisis para otra región."}, {"titulo": "Predicción simple", "aporta": "estima el precio de un producto el próximo mes."}], "objetivos": ["Reunir datos de oferta y precio.", "Identificar temporadas.", "Visualizarlas.", "Escribir una guía de compra."], "habilidades": ["Análisis de series.", "Visualización.", "Lectura de datos públicos.", "Comunicación."], "herramientas": ["Datos públicos de mercados.", "Hoja de cálculo.", "Gráficos."], "lineamientos": ["Indica de dónde salen los datos, con la fecha de consulta, y aclara que son referenciales y no sirven para decidir por tu cuenta qué sembrar o cuánto invertir.", "Aclara que son tendencias generales y que los precios cambian cada año."], "otroSector": "El mismo análisis estacional sirve para planificar compras, personal o campañas en cualquier negocio."}$a36agr$::jsonb,43),
('catalogo-y-guia-ilustrada-de-productos-de-temporada-de-tu-zona','agricultura',array['sociedad']::text[],'Catálogo y guía ilustrada de productos de temporada de tu zona','Crea un catálogo visual de los productos agrícolas de temporada de tu localidad, con una ficha para cada uno que diga cuándo está en su mejor momento, cómo reconocerlo y cómo se usa.','Guía','3 semanas',20,array['Productos de temporada','Guía ilustrada']::text[],array['crear']::text[],'publicos',NULL,'comunicaciones diseno grafico nutricion agronomia educacion marketing ingenieria agroindustrial turismo sintesis de informacion. diseno grafico. redaccion breve. prueba con usuarios. informacion publica agraria. un editor de diseno. fotos propias o dibujos.',$a37agr${"id": "catalogo-y-guia-ilustrada-de-productos-de-temporada-de-tu-zona", "area": "agricultura", "areas2": ["sociedad"], "titulo": "Catálogo y guía ilustrada de productos de temporada de tu zona", "resumen": "Crea un catálogo visual de los productos agrícolas de temporada de tu localidad, con una ficha para cada uno que diga cuándo está en su mejor momento, cómo reconocerlo y cómo se usa.", "tipo": "Guía", "tiempo": "3 semanas", "horas": 20, "etiquetas": ["Productos de temporada", "Guía ilustrada"], "intencion": ["crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Comunicaciones", "Diseño Gráfico", "Nutrición", "Agronomía", "Educación", "Marketing", "Ingeniería Agroindustrial", "Turismo"], "problema": ["Muchos productos locales se conocen poco fuera de su zona. Los consumidores no saben qué hay en cada mes, cómo reconocerlo ni cómo usarlo, y por eso compran lo mismo todo el año.", "Un catálogo claro y atractivo ayuda a valorar lo local y a elegir mejor."], "desarrollar": ["Reúne información pública sobre los productos que se cosechan en tu zona y en qué meses. Elige entre diez y quince, y para cada uno escribe una ficha corta con su temporada, cómo reconocerlo en buen estado, cómo conservarlo y una idea para usarlo.", "Diseña el catálogo con un formato uniforme, usando dibujos o fotos propias. Muéstralo a alguien que no conozca los productos y mejora lo que no se entienda."], "ampliaciones": [{"titulo": "Calendario visual", "aporta": "agrega un calendario que muestre qué hay en cada mes."}, {"titulo": "Versión digital", "aporta": "convierte el catálogo en una página web sencilla."}, {"titulo": "Recetas locales", "aporta": "suma una receta simple por producto."}], "objetivos": ["Reunir información de productos.", "Redactar fichas.", "Diseñar el catálogo.", "Probarlo con un lector."], "habilidades": ["Síntesis de información.", "Diseño gráfico.", "Redacción breve.", "Prueba con usuarios."], "herramientas": ["Información pública agraria.", "Un editor de diseño.", "Fotos propias o dibujos."], "lineamientos": ["Indica de dónde salen los datos, con la fecha de consulta, y aclara que son referenciales y no sirven para decidir por tu cuenta qué sembrar o cuánto invertir.", "No des consejos médicos ni nutricionales personalizados: si mencionas alimentación, apóyate en guías públicas y deriva a profesionales.", "Usa fotos propias o libres de derechos y cita las fuentes."], "otroSector": "La misma lógica de catálogo por temporada sirve para presentar productos o servicios que cambian según la época."}$a37agr$::jsonb,44),
('mercados-locales-vs-cadenas-largas-de-distribucion','agricultura',array['negocios','ciudades']::text[],'Mercados locales vs cadenas largas de distribución','Compara los mismos alimentos en un mercado local y en un supermercado: precio, origen, frescura y variedad, para entender qué aporta cada canal y cuándo conviene uno u otro.','Análisis','3 semanas',22,array['Mercados locales','Distribución']::text[],array['investigar']::text[],'propios',NULL,'ingenieria agroindustrial economia administracion logistica estadistica sociologia marketing ingenieria industrial trabajo de campo. comparacion de precios. tablas. pensamiento critico. lista de compras. cuaderno o celular. hoja de calculo.',$a38agr${"id": "mercados-locales-vs-cadenas-largas-de-distribucion", "area": "agricultura", "areas2": ["negocios", "ciudades"], "titulo": "Mercados locales vs cadenas largas de distribución", "resumen": "Compara los mismos alimentos en un mercado local y en un supermercado: precio, origen, frescura y variedad, para entender qué aporta cada canal y cuándo conviene uno u otro.", "tipo": "Análisis", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Mercados locales", "Distribución"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Agroindustrial", "Economía", "Administración", "Logística", "Estadística", "Sociología", "Marketing", "Ingeniería Industrial"], "problema": ["Un mismo producto puede comprarse en el mercado del barrio o en una cadena grande. Cada canal tiene ventajas: cercanía y frescura por un lado, comodidad y horarios por otro, pero rara vez se comparan con datos.", "Comparar ayuda a decidir con criterio y a entender el papel de los mercados locales."], "desarrollar": ["Elige una canasta de diez alimentos y recorre un mercado local y un supermercado, anotando para cada uno el precio, el origen, el aspecto y si hay variedades. Toma fotos solo de los productos, no de las personas.", "Compara en una tabla el precio promedio, el origen y la frescura percibida. Concluye qué ventajas tiene cada canal y para qué tipo de compra convendría cada uno, siendo cuidadoso de no generalizar a partir de una sola visita."], "ampliaciones": [{"titulo": "Más visitas", "aporta": "repite en otro día y otra semana para ver si cambia."}, {"titulo": "Perspectiva del vendedor", "aporta": "conversa con permiso con un vendedor sobre sus desafíos."}, {"titulo": "Canasta ideal", "aporta": "propón una canasta combinada para equilibrar costo y frescura."}], "objetivos": ["Definir una canasta.", "Recoger datos en dos canales.", "Comparar precio, origen y frescura.", "Concluir con cautela."], "habilidades": ["Trabajo de campo.", "Comparación de precios.", "Tablas.", "Pensamiento crítico."], "herramientas": ["Lista de compras.", "Cuaderno o celular.", "Hoja de cálculo."], "lineamientos": ["Es un experimento pequeño y personal: pocas plantas o pocas muestras durante pocas semanas. No pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir en tu caso.", "Si conversas con productores o vendedores, hazlo con su permiso, sin publicar nombres ni datos de contacto; si prefieren no participar, usa casos inventados.", "No tomes fotos de personas ni de datos privados; pide permiso antes de anotar precios con vendedores."], "otroSector": "El mismo método de comparar dos canales sirve para elegir dónde vender o comprar cualquier producto."}$a38agr$::jsonb,45),
('la-agricultura-familiar-en-tu-mesa','agricultura',array['sociedad','negocios']::text[],'La agricultura familiar en tu mesa','Investiga qué papel tiene la agricultura familiar en el abastecimiento de alimentos del país, qué productos aporta y qué dificultades enfrenta, con datos públicos y casos reales.','Investigación','3 semanas',22,array['Agricultura familiar','Seguridad alimentaria']::text[],array['investigar']::text[],'publicos',NULL,'ingenieria agroindustrial economia administracion logistica estadistica sociologia marketing ingenieria industrial lectura de informes. sintesis. visualizacion de datos. redaccion. censos e informes publicos. hoja de calculo. un editor de documentos.',$a39agr${"id": "la-agricultura-familiar-en-tu-mesa", "area": "agricultura", "areas2": ["sociedad", "negocios"], "titulo": "La agricultura familiar en tu mesa", "resumen": "Investiga qué papel tiene la agricultura familiar en el abastecimiento de alimentos del país, qué productos aporta y qué dificultades enfrenta, con datos públicos y casos reales.", "tipo": "Investigación", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Agricultura familiar", "Seguridad alimentaria"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ingeniería Agroindustrial", "Economía", "Administración", "Logística", "Estadística", "Sociología", "Marketing", "Ingeniería Industrial"], "problema": ["Gran parte de los alimentos que llegan a las mesas viene de familias que cultivan en terrenos pequeños. Su aporte es grande, pero rara vez se ve ni se reconoce, y enfrentan problemas de acceso a mercados y a recursos.", "Conocer su papel ayuda a entender de dónde viene lo que comemos y por qué es importante apoyarlas."], "desarrollar": ["Consulta información pública de instituciones agrarias y censos sobre agricultura familiar. Identifica qué porcentaje de ciertos alimentos proviene de ella, en qué zonas y qué desafíos reportan.", "Presenta los hallazgos en un informe de dos páginas con gráficos simples. Incluye dos o tres ejemplos de alimentos que se cultivan principalmente de esta forma y propón dos maneras de apoyar a estas familias como consumidor."], "ampliaciones": [{"titulo": "Estudio de caso", "aporta": "describe una asociación o cooperativa de agricultores."}, {"titulo": "Por regiones", "aporta": "compara la importancia de la agricultura familiar entre regiones."}, {"titulo": "Voces", "aporta": "incorpora, con permiso, el testimonio de un agricultor."}], "objetivos": ["Reunir datos públicos.", "Identificar aportes y dificultades.", "Presentar ejemplos.", "Proponer formas de apoyo."], "habilidades": ["Lectura de informes.", "Síntesis.", "Visualización de datos.", "Redacción."], "herramientas": ["Censos e informes públicos.", "Hoja de cálculo.", "Un editor de documentos."], "lineamientos": ["Indica de dónde salen los datos, con la fecha de consulta, y aclara que son referenciales y no sirven para decidir por tu cuenta qué sembrar o cuánto invertir.", "Si conversas con productores o vendedores, hazlo con su permiso, sin publicar nombres ni datos de contacto; si prefieren no participar, usa casos inventados.", "Habla de las familias agricultoras con respeto y sin estereotipos; destaca sus aportes."], "otroSector": "El mismo análisis del aporte de actores pequeños sirve para entender el papel de los emprendimientos familiares en cualquier sector."}$a39agr$::jsonb,46),
('cuanto-se-pierde-entre-la-cosecha-y-la-venta','agricultura',array['negocios']::text[],'¿Cuánto se pierde entre la cosecha y la venta?','Investiga cuánto de lo que se cosecha se pierde antes de venderse, en qué etapas y por qué, usando cifras públicas de instituciones agrarias y de alimentación, y explica lo que implica.','Investigación','4 semanas',24,array['Pérdidas de alimentos','Poscosecha']::text[],array['investigar']::text[],'publicos',NULL,'ingenieria agroindustrial economia administracion logistica estadistica sociologia marketing ingenieria industrial lectura de estadisticas. analisis de causas. visualizacion. honestidad con los datos. informes publicos. hoja de calculo. un editor de graficos.',$a40agr${"id": "cuanto-se-pierde-entre-la-cosecha-y-la-venta", "area": "agricultura", "areas2": ["negocios"], "titulo": "¿Cuánto se pierde entre la cosecha y la venta?", "resumen": "Investiga cuánto de lo que se cosecha se pierde antes de venderse, en qué etapas y por qué, usando cifras públicas de instituciones agrarias y de alimentación, y explica lo que implica.", "tipo": "Investigación", "tiempo": "4 semanas", "horas": 24, "etiquetas": ["Pérdidas de alimentos", "Poscosecha"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ingeniería Agroindustrial", "Economía", "Administración", "Logística", "Estadística", "Sociología", "Marketing", "Ingeniería Industrial"], "problema": ["Se habla mucho del desperdicio en los hogares, pero una parte importante de los alimentos se pierde antes de llegar a las tiendas, por falta de almacenamiento, de transporte o de compradores. Esa pérdida no se ve, pero cuesta dinero y recursos.", "Conocer cuánto y dónde se pierde ayuda a decidir dónde mejorar primero."], "desarrollar": ["Reúne cifras públicas de organismos de alimentación y agricultura sobre pérdidas de alimentos entre la cosecha y la venta, para dos o tres productos o para una región. Anota en qué etapas se pierde más y las causas reportadas.", "Organiza las cifras en una tabla y un gráfico y escribe una explicación de qué factores influyen. Ten cuidado de distinguir entre cifras globales y cifras de tu zona, y señala las limitaciones de los datos."], "ampliaciones": [{"titulo": "Valor perdido", "aporta": "convierte las pérdidas en dinero para dimensionar el problema."}, {"titulo": "Soluciones", "aporta": "investiga cómo han reducido pérdidas en otros lugares."}, {"titulo": "Comparar productos", "aporta": "contrasta las pérdidas de un producto fresco y uno que se conserva mejor."}], "objetivos": ["Reunir cifras confiables.", "Identificar etapas y causas.", "Presentar los datos.", "Señalar límites de la información."], "habilidades": ["Lectura de estadísticas.", "Análisis de causas.", "Visualización.", "Honestidad con los datos."], "herramientas": ["Informes públicos.", "Hoja de cálculo.", "Un editor de gráficos."], "lineamientos": ["Indica de dónde salen los datos, con la fecha de consulta, y aclara que son referenciales y no sirven para decidir por tu cuenta qué sembrar o cuánto invertir.", "Distingue entre estimaciones globales y datos locales, y no atribuyas cifras a quienes no las publicaron.", "Si conversas con productores o vendedores, hazlo con su permiso, sin publicar nombres ni datos de contacto; si prefieren no participar, usa casos inventados."], "otroSector": "El mismo análisis de pérdidas en cada etapa sirve para reducir mermas en cualquier cadena de producción."}$a40agr$::jsonb,47),
('reducir-perdidas-de-alimentos-en-un-pequeno-mercado','agricultura',array['negocios','ciudades']::text[],'Reducir pérdidas de alimentos en un pequeño mercado','Imagina un mercado pequeño donde se botan frutas y verduras y diseña un plan con medidas sencillas, como clasificar, vender a precio rebajado o reutilizar, para reducir lo que se pierde.','Plan','3 semanas',22,array['Mercados','Reducir pérdidas']::text[],array['crear','resolver']::text[],'ficticios',NULL,'ingenieria agroindustrial economia administracion logistica estadistica sociologia marketing ingenieria industrial analisis de problemas. estimacion de costos. planificacion. comunicacion. hoja de calculo. un diagrama de causas. un documento de plan.',$a41agr${"id": "reducir-perdidas-de-alimentos-en-un-pequeno-mercado", "area": "agricultura", "areas2": ["negocios", "ciudades"], "titulo": "Reducir pérdidas de alimentos en un pequeño mercado", "resumen": "Imagina un mercado pequeño donde se botan frutas y verduras y diseña un plan con medidas sencillas, como clasificar, vender a precio rebajado o reutilizar, para reducir lo que se pierde.", "tipo": "Plan", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Mercados", "Reducir pérdidas"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Ingeniería Agroindustrial", "Economía", "Administración", "Logística", "Estadística", "Sociología", "Marketing", "Ingeniería Industrial"], "problema": ["En los mercados se pierden alimentos por golpes, maduración o exceso de oferta. Parte se bota, aunque todavía se podría vender, procesar o aprovechar de otras maneras.", "Un plan claro permite ver qué medidas son realistas para un puesto pequeño con pocos recursos."], "desarrollar": ["Con un caso inventado de un mercado con cinco o seis puestos, estima cuánto se pierde por semana y de qué productos. Identifica las causas probables y piensa en medidas como mejor almacenamiento, venta de producto casi maduro con descuento o convenios para aprovechar lo que sobra.", "Estima el costo y el beneficio de cada medida y elige las tres más viables. Redacta un plan con responsables, pasos y una forma sencilla de medir si funciona."], "ampliaciones": [{"titulo": "Con costos", "aporta": "calcula cuánto se ahorraría con cada medida."}, {"titulo": "Participación", "aporta": "diseña cómo involucrar a los comerciantes del mercado."}, {"titulo": "Indicadores", "aporta": "define tres indicadores para seguir las pérdidas en el tiempo."}], "objetivos": ["Estimar las pérdidas.", "Identificar causas.", "Evaluar medidas.", "Redactar un plan."], "habilidades": ["Análisis de problemas.", "Estimación de costos.", "Planificación.", "Comunicación."], "herramientas": ["Hoja de cálculo.", "Un diagrama de causas.", "Un documento de plan."], "lineamientos": ["Usa un caso inventado: no incluyas nombres de comerciantes ni de mercados reales sin su permiso.", "Verifica con las normas de inocuidad antes de proponer vender o regalar alimentos casi maduros.", "Indica de dónde salen los datos, con la fecha de consulta, y aclara que son referenciales y no sirven para decidir por tu cuenta qué sembrar o cuánto invertir."], "otroSector": "El mismo plan de reducir pérdidas sirve para cualquier negocio con productos que se echan a perder, como panaderías o restaurantes."}$a41agr$::jsonb,48),
('un-recetario-con-las-partes-que-solemos-botar','agricultura',array['ambiente']::text[],'Un recetario con las partes que solemos botar','Reúne y prueba recetas que aprovechan partes comestibles que normalmente se descartan, como tallos, cáscaras y hojas, y elabora un recetario sencillo para que otras personas se animen a usarlas.','Guía','3 semanas',18,array['Aprovechamiento','Cocina de aprovechamiento']::text[],array['crear']::text[],'propios',NULL,'nutricion ingenieria alimentaria ingenieria ambiental educacion comunicaciones diseno trabajo social administracion investigacion de fuentes. cocina basica. redaccion de recetas. fotografia. fuentes confiables. cocina de casa. un editor de documentos.',$a42agr${"id": "un-recetario-con-las-partes-que-solemos-botar", "area": "agricultura", "areas2": ["ambiente"], "titulo": "Un recetario con las partes que solemos botar", "resumen": "Reúne y prueba recetas que aprovechan partes comestibles que normalmente se descartan, como tallos, cáscaras y hojas, y elabora un recetario sencillo para que otras personas se animen a usarlas.", "tipo": "Guía", "tiempo": "3 semanas", "horas": 18, "etiquetas": ["Aprovechamiento", "Cocina de aprovechamiento"], "intencion": ["crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Nutrición", "Ingeniería Alimentaria", "Ingeniería Ambiental", "Educación", "Comunicaciones", "Diseño", "Trabajo Social", "Administración"], "problema": ["Se botan muchas partes que sí se pueden comer o aprovechar: tallos de brócoli, hojas de betarraga o cáscaras de ciertos frutos. Muchos no lo hacen por desconocimiento o por falta de ideas de cómo prepararlas.", "Un recetario claro ayuda a perder el miedo y a reducir los desperdicios en casa."], "desarrollar": ["Busca en fuentes confiables qué partes de las frutas y verduras de tu zona son comestibles y cómo se preparan. Elige entre cinco y ocho y prueba una receta sencilla para cada una, anotando ingredientes, pasos y cómo salió.", "Redacta el recetario con instrucciones claras y fotos. Incluye una advertencia de qué partes no deben consumirse y recomienda lavar bien los ingredientes."], "ampliaciones": [{"titulo": "Versión ilustrada", "aporta": "diseña el recetario con fotos y dibujos."}, {"titulo": "Costo", "aporta": "calcula cuánto ahorras al usar estas partes."}, {"titulo": "Receta por temporada", "aporta": "organiza las recetas según el mes de cosecha."}], "objetivos": ["Identificar partes aprovechables.", "Probar recetas.", "Redactar con claridad.", "Advertir de los límites."], "habilidades": ["Investigación de fuentes.", "Cocina básica.", "Redacción de recetas.", "Fotografía."], "herramientas": ["Fuentes confiables.", "Cocina de casa.", "Un editor de documentos."], "lineamientos": ["No des consejos médicos ni nutricionales personalizados: si mencionas alimentación, apóyate en guías públicas y deriva a profesionales.", "Consume solo partes que fuentes confiables señalen como comestibles; si dudas, no las pruebes.", "Lava bien los ingredientes y respeta las alergias de quienes prueben."], "otroSector": "La misma idea de reutilizar sobrantes sirve para pensar en subproductos de cualquier cocina, taller o fábrica."}$a42agr$::jsonb,49),
('aprovechar-frutas-maduras-antes-de-que-se-echen-a-perder','agricultura',array['ambiente']::text[],'Aprovechar frutas maduras antes de que se echen a perder','Prueba formas sencillas de aprovechar frutas muy maduras, como compotas, jugos, batidos o congelado, y arma una guía que diga qué hacer según el tipo de fruta y su estado.','Guía','2 semanas',12,array['Frutas maduras','Aprovechamiento']::text[],array['crear','resolver']::text[],'propios',NULL,'nutricion ingenieria alimentaria ingenieria ambiental educacion comunicaciones diseno trabajo social administracion cocina basica. registro de procesos. redaccion. prueba con usuarios. cocina de casa. recipientes. un editor de documentos.',$a43agr${"id": "aprovechar-frutas-maduras-antes-de-que-se-echen-a-perder", "area": "agricultura", "areas2": ["ambiente"], "titulo": "Aprovechar frutas maduras antes de que se echen a perder", "resumen": "Prueba formas sencillas de aprovechar frutas muy maduras, como compotas, jugos, batidos o congelado, y arma una guía que diga qué hacer según el tipo de fruta y su estado.", "tipo": "Guía", "tiempo": "2 semanas", "horas": 12, "etiquetas": ["Frutas maduras", "Aprovechamiento"], "intencion": ["crear", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Nutrición", "Ingeniería Alimentaria", "Ingeniería Ambiental", "Educación", "Comunicaciones", "Diseño", "Trabajo Social", "Administración"], "problema": ["Las frutas muy maduras se botan aunque todavía sirven para preparar muchos platos. Mucha gente no sabe qué hacer con ellas cuando están blandas o con manchas.", "Una guía con opciones simples permite rescatarlas y reducir el desperdicio doméstico."], "desarrollar": ["Cuando tengas frutas muy maduras pero sin moho, prueba entre tres y cinco formas de aprovecharlas, por ejemplo congelarlas en trozos, hacer una compota o preparar un batido. Anota el procedimiento, el tiempo y cómo quedó.", "Arma una guía que diga, según la fruta y su estado, qué se puede hacer y por cuánto tiempo se conserva el resultado. Pide a alguien que pruebe una receta de tu guía y recoge sus comentarios."], "ampliaciones": [{"titulo": "Fruta por fruta", "aporta": "agrega una ficha para cada fruta de tu zona."}, {"titulo": "Congelado", "aporta": "compara cómo quedan las frutas congeladas frente a frescas."}, {"titulo": "Cuánto rescatas", "aporta": "calcula cuánta fruta salvas en un mes con tus recetas."}], "objetivos": ["Probar formas de aprovechar.", "Registrar el procedimiento.", "Elaborar una guía.", "Probarla con otra persona."], "habilidades": ["Cocina básica.", "Registro de procesos.", "Redacción.", "Prueba con usuarios."], "herramientas": ["Cocina de casa.", "Recipientes.", "Un editor de documentos."], "lineamientos": ["No pruebes ni consumas alimentos que parezcan echados a perder; el objetivo es observar, no arriesgarse.", "No des consejos médicos ni nutricionales personalizados: si mencionas alimentación, apóyate en guías públicas y deriva a profesionales.", "Descarta las frutas con moho o mal olor; el aprovechamiento es para frutas maduras en buen estado."], "otroSector": "La misma idea de dar una segunda vida a lo que está por perderse sirve para productos en cualquier negocio."}$a43agr$::jsonb,50),
('excedentes-de-un-comedor-como-aprovecharlos-sin-desperdiciarlos','agricultura',array['sociedad','ambiente']::text[],'Excedentes de un comedor: cómo aprovecharlos sin desperdiciarlos','Plantea qué haría un comedor, real o imaginario, con los alimentos que le sobran: ajustar porciones, ofrecer segundas rondas, reutilizar ingredientes o gestionar donaciones respetando las normas.','Plan','3 semanas',22,array['Excedentes','Comedores']::text[],array['crear','resolver']::text[],'ficticios',NULL,'nutricion ingenieria alimentaria ingenieria ambiental educacion comunicaciones diseno trabajo social administracion estimacion. planificacion. pensamiento critico. redaccion de planes. hoja de calculo. un diagrama de procesos. un documento de plan.',$a44agr${"id": "excedentes-de-un-comedor-como-aprovecharlos-sin-desperdiciarlos", "area": "agricultura", "areas2": ["sociedad", "ambiente"], "titulo": "Excedentes de un comedor: cómo aprovecharlos sin desperdiciarlos", "resumen": "Plantea qué haría un comedor, real o imaginario, con los alimentos que le sobran: ajustar porciones, ofrecer segundas rondas, reutilizar ingredientes o gestionar donaciones respetando las normas.", "tipo": "Plan", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Excedentes", "Comedores"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Nutrición", "Ingeniería Alimentaria", "Ingeniería Ambiental", "Educación", "Comunicaciones", "Diseño", "Trabajo Social", "Administración"], "problema": ["En los comedores, a veces sobran alimentos que no se sirvieron, y muchos terminan en la basura. Hay maneras de reducir lo que sobra y de aprovechar mejor lo que queda, pero deben hacerse con cuidado para no afectar la seguridad de la comida.", "Un plan claro ayuda a evitar el desperdicio sin poner en riesgo la salud."], "desarrollar": ["Con un caso imaginario de un comedor que sirve cien raciones al día, estima cuánto podría sobrar y qué tipo de alimentos son. Piensa en medidas como cocinar por tandas, ajustar porciones, planificar el menú según asistencia y reutilizar de forma segura ingredientes no servidos.", "Identifica qué normas de inocuidad deberían tenerse en cuenta antes de donar o reutilizar. Redacta un plan breve con medidas, responsables y un modo sencillo de medir lo que se desperdicia."], "ampliaciones": [{"titulo": "Registro de sobras", "aporta": "diseña una planilla simple para anotar lo que sobra cada día."}, {"titulo": "Menú flexible", "aporta": "propón cómo ajustar el menú según los consumos."}, {"titulo": "Convenios", "aporta": "piensa cómo coordinar con organizaciones, siempre dentro de las normas."}], "objetivos": ["Estimar lo que sobra.", "Plantear medidas.", "Identificar normas de inocuidad.", "Redactar un plan."], "habilidades": ["Estimación.", "Planificación.", "Pensamiento crítico.", "Redacción de planes."], "herramientas": ["Hoja de cálculo.", "Un diagrama de procesos.", "Un documento de plan."], "lineamientos": ["Usa un caso inventado y no te presentes como autoridad sanitaria; consulta las normas de inocuidad vigentes antes de proponer donaciones.", "No des consejos médicos ni nutricionales personalizados: si mencionas alimentación, apóyate en guías públicas y deriva a profesionales.", "Indica de dónde salen los datos, con la fecha de consulta, y aclara que son referenciales y no sirven para decidir por tu cuenta qué sembrar o cuánto invertir."], "otroSector": "El mismo plan de ajustar la producción a la demanda sirve en restaurantes, panaderías y cualquier servicio con productos perecibles."}$a44agr$::jsonb,51)
